/* PYWEL BESTIARIUM | Pure client-side JavaScript; no build process or API calls. */
(() => {
'use strict';
const APP='pywel-bestiary-v1', UNKNOWN='Nicht verifiziert';
const base=Array.isArray(window.CD_ENTRIES)?window.CD_ENTRIES:[];
const src=window.CD_SOURCES||{};
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const text=v=>esc(v||'Unbekannt');
const url=v=>{try{const u=new URL(v);return ['https:','http:'].includes(u.protocol)?u.href:null}catch{return null}};
const slug=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,90);
const initial={version:1,progress:{},custom:[],overrides:{},settings:{light:false,spoilers:false},recent:[]};
let store;
try{const old=JSON.parse(localStorage.getItem(APP)||'null');store={...initial,...old,progress:old?.progress||{},custom:Array.isArray(old?.custom)?old.custom:[],overrides:old?.overrides||{},settings:{...initial.settings,...(old?.settings||{})},recent:Array.isArray(old?.recent)?old.recent:[]}}catch{store=structuredCloneSafe(initial)};
const filter={search:'',category:'',region:'',difficulty:'',element:'',weakness:'',type:'',status:'',knowledge:'',favorites:false,sort:'name',view:'grid'};
let route='start',editing=null,lastPage='lexikon',toastTimer=null;
const categories={
 'Steinwürmer':['worm','Steinwürmer'], 'Dornenranken':['vine','Dornenranken'], 'Getarnte Pflanzen':['plant','Getarnte Pflanzen'],
 'Spinnen & Insekten':['spider','Spinnen & Insekten'], 'Krabben & Panzerwesen':['crab','Krabben & Panzerwesen'],
 'Magische Wesen':['magic','Magische Wesen'], 'Mechanische Kreaturen':['mech','Mechanische Kreaturen'],
 'Fliegende Kreaturen':['dragon','Fliegende Kreaturen'], 'Wilde Bestien':['beast','Wilde Bestien'],
 'Legendäre Tiere':['legend','Legendäre Tiere'],'Optionale Weltbosse':['boss','Optionale Weltbosse'],'Storybosse':['boss','Storybosse']};
const art=e=>{const f=String(e.image||'');if(/^assets\/[a-zA-Z0-9_.-]+\.(png|jpg|jpeg|webp|svg)$/i.test(f)&&!f.includes('..'))return f;const t=categories[e.category]?.[0]||'boss';return 'assets/'+t+'.svg'};
const glossary={
 'Force Palm':'Energiestoß. Wird in mehreren Bossmechaniken zur Unterbrechung oder für gezielten Schaden eingesetzt.',
 'Axiom Force':'Kraft zum Fixieren oder Bewegen von Objekten und Gegnern. Nutzung ist situationsabhängig.',
 'Nature’s Retribution':'Erweiterung von Nature’s Snare: gegnerische Projektile fangen und zurückwerfen.',
 'Nature’s Snare':'Naturfähigkeit zum Interagieren mit gegnerischen Projektilen.',
 'Turning Slash':'Wirbel-/Drehangriff, in Krabben-Bossguides zum Zerstören von Kristallen beschrieben.',
 'Gift':'Gift kann Schaden über Zeit verursachen. Konkrete Resistenz des Gegners nicht daraus ableiten.',
 'Feuer':'Feuerschaden; eine bestätigte Schwäche wird für jeden Gegner separat ausgewiesen.',
 'Blitz':'Elektrischer Schaden; eine bestätigte Resistenz muss gegnerspezifisch belegt werden.',
 'Eis':'Frost- oder Kälteschaden; eine bestätigte Resistenz muss gegnerspezifisch belegt werden.'
};
const hint=x=>{const k=Object.keys(glossary).find(t=>String(x).toLowerCase().includes(t.toLowerCase()));return k?`<abbr title="${esc(glossary[k])}" style="cursor:help;text-decoration:underline dotted var(--gold)">${esc(x)}</abbr>`:esc(x)};
const items=()=>[...base.map(x=>({...x,...(store.overrides[x.id]||{})})),...store.custom].filter(e=>e?.id&&e.en);
const byId=id=>items().find(e=>e.id===id);
const pget=id=>store.progress[id]||{};
const pset=(id,partial)=>{store.progress[id]={...pget(id),...partial};save();updateSidebar()};
function structuredCloneSafe(o){return JSON.parse(JSON.stringify(o))}
function save(){try{localStorage.setItem(APP,JSON.stringify(store));return true}catch{notify('Browser-Speicher nicht verfügbar: Daten bitte als JSON exportieren.');return false}}
function notify(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),4300)}
function status(){const all=items(),k=all.filter(e=>pget(e.id).defeated).length,w=all.filter(e=>pget(e.id).knowledge).length,r=all.filter(e=>pget(e.id).rewards).length;
 return {all:all.length,k,w,r,missing:all.length-k,pct:all.length?Math.round(k/all.length*100):0,knowledgePct:all.length?Math.round(w/all.length*100):0,full:all.length?Math.round((k+w+r)/(all.length*3)*100):0,favs:all.filter(e=>pget(e.id).favorite).length}}
function updateSidebar(){const s=status();$('sidebar-count').textContent=s.all;$('side-pct').textContent=s.pct+' %';$('side-progress').style.width=s.pct+'%';$('theme-toggle').textContent=store.settings.light?'☾':'☼';$('spoiler-toggle').innerHTML=`◈ <span class="desktop-only">Spoiler ${store.settings.spoilers?'an':'aus'}</span>`;document.body.classList.toggle('theme-light',!!store.settings.light);document.body.classList.toggle('theme-dark',!store.settings.light)}
const getHash=()=>{const h=decodeURIComponent((location.hash||'#/start').replace(/^#\/?/,''));const [a,b]=h.split('/');return {a:a||'start',b:b||''}};
const goto=(page)=>{location.hash='#/'+page};
function navRender(){const active=route==='monster'?lastPage:route;document.querySelectorAll('[data-route]').forEach(a=>{a.classList.toggle('active',a.dataset.route===active);if(a.dataset.route===active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});const names={start:'Übersicht',lexikon:'Monsterlexikon',boss:'Boss-Guide',fundorte:'Fundorte',sammlung:'Meine Sammlung',kampf:'Kampfsystem & PS5',daten:'Datenbank bearbeiten',quellen:'Quellen & Änderungen',rechtliches:'Über & Rechtliches',monster:'Monstereintrag'};$('breadcrumb').textContent=names[route]||names.start;updateSidebar()}
function setPage(html){$('content').innerHTML=html;}
function sectionHead(kicker,title,desc,extra=''){return `<div class="page-head"><div><div class="eyebrow">${esc(kicker)}</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div>${extra}</div>`}
function btn(s,label,cls='ghost'){return `<button class="btn ${cls}" data-action="${esc(s)}">${esc(label)}</button>`}
function statBox(num,title,extra=''){return `<div class="stat"><strong class="value">${esc(num)}</strong><div class="caption">${esc(title)}</div>${extra?`<div class="line">${esc(extra)}</div>`:''}</div>`}
function shownName(e){return e.spoiler&&!store.settings.spoilers?`Storyboss · Kapitel ${e.chapter||'?'}`:e.de}
function badge(e){return e.kind==='Storyboss'?'STORYBOSS':e.kind.includes('Weltboss')?'WELTBOSS':e.kind==='Legendäres Tier'?'LEGENDÄR':e.category.toUpperCase()}
function card(e){const pr=pget(e.id),spoiler=e.spoiler&&!store.settings.spoilers;return `<article class="monster-card" data-id="${esc(e.id)}"><div class="card-art" data-open="${esc(e.id)}" role="link" tabindex="0" aria-label="${esc(spoiler?'Storyboss öffnen':e.de+' öffnen')}"><img src="${art(e)}" alt="Originale Symbolillustration, keine Spielaufnahme" loading="lazy"><span class="tag">${esc(badge(e))}</span><button type="button" class="fav-float ${pr.favorite?'is-on':''}" data-track="favorite" data-id="${esc(e.id)}" aria-label="Favorit umschalten" aria-pressed="${!!pr.favorite}">${pr.favorite?'★':'☆'}</button></div><div class="card-info"><h3>${esc(shownName(e))}</h3><div class="card-en">${spoiler?'Name verborgen':esc(e.en===e.de?'Originalname bekannt':e.en)}</div><p class="card-desc">${spoiler?'Inhalt verborgen: Storyspoiler sind deaktiviert.':esc(e.description)}</p><div class="card-bottom"><label class="check-row"><input type="checkbox" data-track="defeated" data-id="${esc(e.id)}" ${pr.defeated?'checked':''}>Besiegt</label><button class="card-link" data-open="${esc(e.id)}">Guide ansehen →</button></div></div></article>`}
function cards(list){return list.length?`<div id="result-cards" class="${filter.view==='list'?'list-cards':'grid-cards'}">${list.map(card).join('')}</div>`:`<div class="empty"><h3>Keine passenden Einträge</h3><p>Suchbegriff oder Filter anpassen. Unbekannte Angaben werden nicht automatisch geraten.</p>${btn('clear-filters','Filter zurücksetzen')}</div>`}
function reportCount(){const n=filterItems().length;return `${n} von ${items().length} Einträgen`}
function filterItems(){let a=items();const q=filter.search.toLocaleLowerCase('de');if(q)a=a.filter(x=>[x.de,x.en,x.category,x.kind,x.region,x.location,x.element,x.weakness,x.quest,x.description,x.attacks,x.strategy,x.loot].join(' ').toLocaleLowerCase('de').includes(q));if(filter.category)a=a.filter(x=>x.category===filter.category);if(filter.region)a=a.filter(x=>x.region===filter.region);if(filter.difficulty)a=a.filter(x=>x.difficulty===filter.difficulty);if(filter.element)a=a.filter(x=>x.element.toLowerCase().includes(filter.element.toLowerCase()));if(filter.weakness)a=a.filter(x=>x.weakness.toLowerCase().includes(filter.weakness.toLowerCase()));if(filter.type)a=a.filter(x=>filter.type==='story'?x.kind==='Storyboss':filter.type==='optional'?x.kind.includes('Weltboss'):filter.type==='legend'?x.kind.includes('Tier'):true);if(filter.status)a=a.filter(x=>filter.status==='yes'?!!pget(x.id).defeated:!pget(x.id).defeated);if(filter.knowledge)a=a.filter(x=>filter.knowledge==='yes'?!!pget(x.id).knowledge:!pget(x.id).knowledge);if(filter.favorites)a=a.filter(x=>pget(x.id).favorite);a.sort((x,y)=>{if(filter.sort==='region')return x.region.localeCompare(y.region,'de')||x.de.localeCompare(y.de,'de');if(filter.sort==='difficulty'){const rank={'Unbekannt':0,'Leicht':1,'Mittel':2,'Schwer':3,'Sehr schwer':4};return (rank[y.difficulty]||0)-(rank[x.difficulty]||0)||x.de.localeCompare(y.de,'de')}return x.de.localeCompare(y.de,'de')});return a}
function selectHTML(id,label,options,val){return `<label class="field"><span>${esc(label)}</span><select class="select" id="${esc(id)}">${options.map(([v,l])=>`<option value="${esc(v)}" ${val===v?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`}
const optionsFrom=(arr)=>[['','Alle'],...Array.from(new Set(arr)).sort((a,b)=>a.localeCompare(b,'de')).map(v=>[v,v])];
function filterUI(){let all=items();return `<div class="filters"><div class="searchbox"><input class="input" id="filter-search" value="${esc(filter.search)}" type="search" placeholder="Namen, Fähigkeiten, Beute, Fundorte suchen…" aria-label="Monster durchsuchen"></div><div class="filter-grid">
${selectHTML('f-category','Kategorie',optionsFrom(all.map(x=>x.category)),filter.category)}
${selectHTML('f-region','Region',optionsFrom(all.map(x=>x.region)),filter.region)}
${selectHTML('f-difficulty','Schwierigkeit',optionsFrom(all.map(x=>x.difficulty)),filter.difficulty)}
${selectHTML('f-element','Element',[['','Alle'],['Gift','Gift'],['Feuer','Feuer'],['Blitz','Blitz'],['Eis','Eis']],filter.element)}
${selectHTML('f-weakness','Schwachstelle',[['','Alle'],['Feuer','Feuer'],['Auge','Auge'],['Unbekannt','Unbekannt']],filter.weakness)}
${selectHTML('f-type','Gegnertyp',[['','Alle'],['story','Storyboss'],['optional','Weltboss'],['legend','Legendäres Tier']],filter.type)}
${selectHTML('f-status','Status',[['','Alle'],['yes','Besiegt'],['no','Nicht besiegt']],filter.status)}
${selectHTML('f-knowledge','Wissen',[['','Alle'],['yes','Freigeschaltet'],['no','Nicht freigeschaltet']],filter.knowledge)}
${selectHTML('f-sort','Sortieren',[['name','Alphabetisch'],['region','Region'],['difficulty','Schwierigkeit (absteigend)']],filter.sort)}
</div><div class="filter-footer"><div class="actions"><label class="toggle"><input id="f-fav" type="checkbox" ${filter.favorites?'checked':''}>Nur Favoriten</label><button class="btn ghost small" data-action="clear-filters">Zurücksetzen</button></div><div class="actions"><span id="filter-count" class="filter-count">${reportCount()}</span><div class="view-switch" aria-label="Ansicht"><button data-view="grid" class="${filter.view==='grid'?'active':''}">▦ Karten</button><button data-view="list" class="${filter.view==='list'?'active':''}">☷ Liste</button></div></div></div></div>`}
function renderFiltered(){const old=$('result-cards')||document.querySelector('#lex-results .empty');if(!old)return;const area=$('lex-results');area.innerHTML=cards(filterItems());$('filter-count').textContent=reportCount()}
function dashboard(){const s=status();const recent=store.recent.map(byId).filter(Boolean).slice(0,3);const legends=items().filter(e=>e.kind==='Optionaler Weltboss'&&(['White Horn, Shepherd of Souls','Karanda'].includes(e.en)));const featured=legends.length?legends:items().filter(e=>e.category==='Legendäre Tiere').slice(0,2);const showCats=Object.keys(categories);return `<section class="hero"><div class="hero-body"><div class="eyebrow">DER INOFFIZIELLE GUIDE ZU CRIMSON DESERT</div><h1>Die Schatten <br>von <em>Pywel</em></h1><p>Entdecke bekannte Kreaturen, finde dokumentierte Bosse und halte deine Fortschritte fest. Jede unbekannte Angabe bleibt als solche markiert.</p><div class="hero-stats"><div><strong>${s.all}</strong><span>Erfasste Einträge</span></div><div><strong>${s.k}</strong><span>Besiegt</span></div><div><strong>${s.pct} %</strong><span>Abschluss</span></div></div><div class="actions"><a class="btn primary" href="#/lexikon">Monster entdecken ↗</a><a class="btn ghost" href="#/sammlung">Meine Sammlung</a></div></div></section>
 <div class="callout"><strong>Recherchehinweis:</strong> Stand 27. Oktober 2026. „Charting the Unknown“ erscheint laut Pearl Abyss erst am 29. Oktober. DLC-Kreaturen sind daher noch nicht als bestätigte Einträge enthalten. Die Kategorie-Illustrationen sind eigenständig; der separat gekennzeichnete Medienbereich enthält offizielle Aufnahmen mit Quellenangabe.</div>
 <section class="section pa-media"><div class="section-heading"><div><span class="eyebrow">SPIELIMPRESSIONEN · © PEARL ABYSS CORP.</span><h2>Offizielle Bilder aus Pywel</h2><p>Von Pearl Abyss veröffentlichtes Bildmaterial. Nur allgemeine Eindrücke, keine gesicherte Zuordnung zu einem Monster.</p></div><a class="link" href="#/rechtliches">Bildrechte & Herkunft →</a></div><div class="pa-media-grid"><figure><img loading="lazy" src="https://s1.pearlcdn.com/cd/brand/media_GLOBAL/2026/09/07/def60b5502a20260907070613885.jpg" alt="Offizieller Crimson-Desert-Screenshot mit einer verschneiten Landschaft und einer Spielfigur"><figcaption>Offizieller Screenshot – Crimson Desert · © Pearl Abyss Corp. <a href="https://crimsondesert.pearlabyss.com/en-us/Media" target="_blank" rel="noopener noreferrer">Quelle ↗</a></figcaption></figure><figure><img loading="lazy" src="https://s1.pearlcdn.com/cd/brand/media_GLOBAL/2026/10/22/d14095a80a720261022015903777.jpg" alt="Offizielles Vorschaubild zu Charting the Unknown: Taucher und Meeresschildkröte"><figcaption>Offizielle Vorschau zu „Charting the Unknown“ (noch nicht veröffentlicht am 27.10.2026) · © Pearl Abyss Corp. <a href="https://crimsondesert.pearlabyss.com/en-us/Media" target="_blank" rel="noopener noreferrer">Quelle ↗</a></figcaption></figure></div><p class="small-note">Die Screenshots werden vom offiziellen Pearl-Abyss-Bildserver geladen und können bei fehlender Internetverbindung nicht erscheinen.</p></section>
 <section class="section"><div class="section-heading"><div><span class="eyebrow">DEIN FORTSCHRITT</span><h2>Auf dem Weg zum vollständigen Bestiarium</h2></div><a class="link" href="#/sammlung">Fortschritt öffnen →</a></div><div class="stat-grid">${statBox(s.all,'Bekannte Einträge')}${statBox(s.k,'Besiegt',s.missing+' noch offen')}${statBox(s.w,'Wissen freigeschaltet')}${statBox(s.full+' %','Gesamtfortschritt','3 Ziele je Monster')}</div></section>
 <section class="section"><div class="section-heading"><div><span class="eyebrow">DAS BESTIARIUM</span><h2>Erkunde die Kategorien</h2></div><a class="link" href="#/lexikon">Alle anzeigen →</a></div><div class="cat-grid">${showCats.map(cat=>`<button type="button" class="cat-card" data-category="${esc(cat)}"><img src="assets/${categories[cat][0]}.svg" alt="" loading="lazy"><span><strong>${esc(cat)}</strong><small>${items().filter(x=>x.category===cat).length} Einträge</small></span></button>`).join('')}</div></section>
 <section class="section"><div class="section-heading"><div><span class="eyebrow">HERAUSFORDERUNG</span><h2>Legendäre Begegnungen</h2></div><a class="link" href="#/boss">Boss-Guide ansehen →</a></div><div class="feature-grid">${featured.map(e=>`<div class="feature"><img src="${art(e)}" alt="Symbolillustration" loading="lazy"><div><h3>${esc(e.de)}</h3><p>${esc(e.region)} · ${esc(e.location)}</p><button class="card-link" data-open="${esc(e.id)}">Guide öffnen →</button></div></div>`).join('')}</div></section>
 ${recent.length?`<section class="section"><div class="section-heading"><div><span class="eyebrow">ZU LETZT ANGESEHEN</span><h2>Deine Spuren</h2></div></div><div class="grid-cards">${recent.map(card).join('')}</div></section>`:''}`}
function lexikon(){return sectionHead('117 RECHERCHIERTE EINTRÄGE','Monsterlexikon','Kombiniere Filter, suche nach Originalnamen oder wechsle zwischen Listen- und Kartenansicht.')+filterUI()+`<div id="lex-results">${cards(filterItems())}</div>`}
function bossPage(){const story=items().filter(x=>x.kind==='Storyboss').sort((a,b)=>(a.chapter||0)-(b.chapter||0));const optional=items().filter(x=>x.kind.includes('Weltboss')&&x.kind!=='Storyboss');const group=(arr)=>arr.map(e=>`<div class="boss-row"><img src="${art(e)}" loading="lazy" alt="Symbolillustration"><div class="boss-details"><strong>${esc(shownName(e))}</strong><small>${esc(e.region)} · ${e.kind==='Storyboss'?('Kapitel '+e.chapter):esc(e.location)}</small></div><label class="check-row"><input type="checkbox" data-track="defeated" data-id="${esc(e.id)}" ${pget(e.id).defeated?'checked':''}>Besiegt</label><button class="btn small ghost" data-open="${esc(e.id)}">Guide →</button></div>`).join('');const chapters=[...new Set(story.map(x=>x.chapter))].sort((a,b)=>a-b);
 return sectionHead('HAUPTSTORY & WELTBOSSE','Boss-Guide','Storybosse nach Kapitel und optionale Begegnungen. Namen und Mechaniken werden ohne Spoiler-Freigabe verborgen.',btn('toggle-spoiler',store.settings.spoilers?'Spoiler verbergen':'Storyspoiler anzeigen'))+`<div class="callout"><strong>Storyschutz:</strong> Bei deaktivierten Spoilern bleiben Namen und Details der Hauptstorygegner verborgen. Der Fortschritt kann trotzdem markiert werden.</div><section class="section"><div class="detail-block"><h2>Boss-Revanche – offiziell seit Patch 1.05.00</h2><p>Besiegte Bosse können über ihre <strong>Erinnerungsfragmente</strong> erneut herausgefordert werden. Öffne bei einem zuvor besiegten Boss die Laterne am Kampfort oder finde die Stelle unter Tagebuch → Wissen → Erinnerungsfragmente → Bosse. <strong>Erinnern</strong> wiederholt die Ausgangsbegegnung, <strong>Resonieren</strong> passt stärkere Spielerwerte an. Die verwendeten Verbrauchsgegenstände werden nach dem Versuch wiederhergestellt; Revanche-Kämpfe geben keine zusätzliche Beute (Stand Patch 1.05).</p><p>${store.settings.spoilers?`Zusätzliche offiziell genannte Revanche-Orte aus Patch 1.07: Muskan – Knochengrube; Verdorbener Caliburn – Festung Muskete; Goyen – Spitze der Sonne; Draven, der Krähenbeschwörer – Kirche von West-Demeniss; Uhrwerk-Weißhorn – Tor der Technologie. Manche Orte wurden in späteren Patches geändert; maßgeblich ist das aktuelle Ingame-Tagebuch.`:`Fünf weitere Boss-Revanche-Begegnungen wurden mit Patch 1.07 hinzugefügt. Namen und Fundorte bleiben bei deaktiviertem Spoiler-Modus verborgen.`}</p><div class="sources-list"><a target="_blank" rel="noopener noreferrer" href="https://crimsondesert.pearlabyss.com/en-US/News/Notice/Detail?_boardNo=88">Offizielle Patchnotes 1.05.00 ↗</a><a target="_blank" rel="noopener noreferrer" href="https://crimsondesert.pearlabyss.com/de-DE/News/Notice/Detail?_boardNo=92">Offizielle Patchnotes 1.07.00 ↗</a></div></div></section><section class="section"><h2>Hauptgeschichte</h2>${chapters.map(ch=>`<div class="boss-group"><div class="group-title"><span>${String(ch).padStart(2,'0')}</span><h3>Kapitel ${ch}</h3></div>${group(story.filter(x=>x.chapter===ch))}</div>`).join('')}</section><section class="section"><h2>Optionale Weltbosse</h2><div>${group(optional)}</div></section>`}
function sourcesLinks(e){const links=(e.sources||[]).map(x=>url(x)).filter(Boolean);return links.length?links.map((x,i)=>`<a href="${esc(x)}" target="_blank" rel="noopener noreferrer">Quelle ${i+1} · ${esc(new URL(x).hostname)} ↗</a>`).join(''):'<span class="muted">Keine Quelle eingetragen</span>'}
function progressControls(e){const p=pget(e.id);return `<div class="tracking-options"><label><input class="tracking-checkbox" type="checkbox" data-track="defeated" data-id="${esc(e.id)}" ${p.defeated?'checked':''}>Besiegt</label><label><input class="tracking-checkbox" type="checkbox" data-track="knowledge" data-id="${esc(e.id)}" ${p.knowledge?'checked':''}>Wissen freigeschaltet</label><label><input class="tracking-checkbox" type="checkbox" data-track="rewards" data-id="${esc(e.id)}" ${p.rewards?'checked':''}>Alle Belohnungen erhalten</label><label><input class="tracking-checkbox" type="checkbox" data-track="favorite" data-id="${esc(e.id)}" ${p.favorite?'checked':''}>Favorit</label><div class="kv"><label for="kills-${esc(e.id)}">Besiegungen</label><div class="actions"><button class="btn-square" data-action="decrement-kills" data-id="${esc(e.id)}" aria-label="Besiegungen verringern">−</button><input class="input" style="width:67px;text-align:center;padding:7px" id="kills-${esc(e.id)}" type="number" min="0" max="999999" value="${Number(p.kills)||0}" data-kills="${esc(e.id)}"><button class="btn-square" data-action="increment-kills" data-id="${esc(e.id)}" aria-label="Besiegungen erhöhen">+</button></div></div></div><label class="note-label" for="note-${esc(e.id)}">Persönliche Notizen (automatisch gespeichert)</label><textarea class="textarea" id="note-${esc(e.id)}" data-note="${esc(e.id)}" placeholder="Meine Strategie, Fundortnotizen, Beute…">${esc(p.notes||'')}</textarea>`}
const kbds=a=>a.map(k=>{const css=k==='✕'?'ps-x':k==='○'?'ps-o':k==='△'?'ps-tri':k==='□'?'ps-square':'';return `<kbd class="kbd ${css}" title="PS5-Taste ${esc(k)}">${esc(k)}</kbd>`}).join(' ');
function detail(e){if(!e)return `<div class="empty"><h2>Eintrag nicht gefunden</h2><a href="#/lexikon" class="btn ghost">Zurück zum Lexikon</a></div>`;
 if(e.spoiler&&!store.settings.spoilers)return `<div class="page-head"><div><span class="eyebrow">STORYBOSS · KAPITEL ${e.chapter}</span><h1>Eintrag verborgen</h1></div></div><div class="spoiler-gate"><div style="font-size:3.2rem">⚔</div><h2>Dieser Guide enthält Storyspoiler</h2><p>Bossname, Kampfmuster und Belohnungen werden erst nach Freigabe gezeigt.</p><button class="btn primary" data-action="toggle-spoiler">Spoiler für Storybosse einschalten</button> <a class="btn ghost" href="#/boss">Zurück</a></div>`;
 const p=pget(e.id);const related=items().filter(o=>o.id!==e.id&&o.category===e.category).slice(0,3);const confidence={'guide':['Guide belegt','ok'],'mixed':['Teilweise recherchiert','warn'],'name':['Name bestätigt · Detaildaten offen','warn']}[e.confidence]||['Nicht geprüft','warn'];const chapter=e.chapter?'Kapitel '+e.chapter:'Unbekannt';
 return `<div class="page-head"><div class="actions"><button class="btn ghost small" data-action="go-back">← Zurück</button><span class="eyebrow">${esc(e.category)} / ${esc(e.kind)}</span></div><div class="actions no-print"><button class="btn ghost small" data-action="print">⎙ Guide drucken</button><button class="btn ghost small" data-action="edit-record" data-id="${esc(e.id)}">✎ Bearbeiten</button></div></div>
 <div class="detail-hero"><img src="${art(e)}" alt="Freie künstlerische Symbolillustration, keine Spielaufnahme"><div><span class="tag">${esc(e.kind)}</span><h1>${esc(e.de)}</h1><p>${esc(e.en)} ${e.en!==e.de?'· deutsche Arbeitsübersetzung':''}</p><div class="pillrow"><span class="pill">${esc(e.region)}</span><span class="pill">${esc(e.difficulty)}</span><span class="pill ${confidence[1]}">${esc(confidence[0])}</span></div></div></div>
 <div class="detail-layout"><div class="detail-main"><section class="detail-block"><h2>Wissenseintrag</h2><p>${text(e.description)}</p><div class="fact-grid"><dl><dt>Region</dt><dd>${text(e.region)}</dd></dl><dl><dt>Fundort</dt><dd>${text(e.location)}</dd></dl><dl><dt>Schwierigkeit</dt><dd>${text(e.difficulty)}</dd></dl><dl><dt>Kapitel / Quest</dt><dd>${text(e.quest)}${e.chapter?' · '+chapter:''}</dd></dl><dl><dt>Element</dt><dd>${hint(e.element)}</dd></dl><dl><dt>Resistenzen</dt><dd>${text(e.resistance)}</dd></dl><dl><dt>Schwachstellen</dt><dd>${text(e.weakness)}</dd></dl><dl><dt>Beute / Belohnungen</dt><dd>${text(e.loot)}</dd></dl></div>${e.spawns?.length?`<h3>Dokumentierte Fundort-Hinweise</h3><div class="pillrow">${e.spawns.map(t=>`<span class="pill">⌖ ${esc(t)}</span>`).join('')}</div>`:''}</section>
 <section class="detail-block"><h2>Kampf-Guide</h2><div class="pillrow"><span class="pill ${confidence[1]}">${esc(confidence[0])}</span><span class="pill">Keine garantierten Exploits</span></div><h3>Beobachtete Angriffsmuster</h3><p>${text(e.attacks)}</p><h3>Vorgehensweise</h3><p>${text(e.strategy)}</p><ol class="guide-steps">${(Array.isArray(e.steps)?e.steps:[]).map(s=>`<li>${esc(s)}</li>`).join('')}</ol><h3>Waffen & Fähigkeiten</h3><p><strong>Waffen:</strong> ${text(e.weapons)}. <strong>Fähigkeiten:</strong> ${e.skills?.length?e.skills.map(hint).join(', '):'Nicht gegnerspezifisch bestätigt'}.</p><h3>PS5-Grundsteuerung</h3><p>${kbds(e.buttons?.length?e.buttons:['R1','R2','○','L1'])}</p><p class="small-note">Die aufgeführten Tasten sind Basisaktionen. Eine gegnerspezifische Tastenkombination wird nicht behauptet, sofern nicht quellenbelegt. Details unter „Kampfsystem & PS5“.</p></section>
 <section class="detail-block"><h2>Verwandte Kreaturen</h2>${related.length?`<div class="feature-grid">${related.map(x=>`<div class="feature"><img src="${art(x)}" alt="Symbolillustration"><div><h3>${esc(shownName(x))}</h3><p>${esc(x.category)}</p><button class="card-link" data-open="${esc(x.id)}">Eintrag ansehen →</button></div></div>`).join('')}</div>`:'<p>Keine direkt verwandten Einträge erfasst.</p>'}</section>
 </div><aside class="detail-side"><section class="detail-block"><h2>Deine Sammlung</h2>${progressControls(e)}</section><section class="detail-block"><h2>Recherche & Quellen</h2><div class="pillrow"><span class="pill ${confidence[1]}">${esc(confidence[0])}</span></div><p class="source-date">Zuletzt redaktionell geprüft: ${esc(e.verified||'Unbekannt')}</p><p class="small-note">${text(e.notes)}</p><div class="sources-list">${sourcesLinks(e)}</div></section><section class="detail-block"><h2>Fundortsuche</h2><p class="small-note">Exakte Kartenkoordinaten wurden nur übernommen, wenn bestätigt; für diesen Datensatz liegt keine verifizierte Ingame-Koordinate vor.</p><a class="btn ghost small" href="${src.map||'https://crimsondesert.th.gl/guides'}" target="_blank" rel="noopener noreferrer">Externe interaktive Karte ↗</a></section></aside></div>`}
function visit(id){store.recent=[id,...store.recent.filter(x=>x!==id)].slice(0,8);save()}
function ratioBars(groupKey){const groups={};for(const e of items()){const key=e[groupKey]||'Unbekannt';groups[key]??={all:0,done:0};groups[key].all++;if(pget(e.id).defeated)groups[key].done++};const data=Object.entries(groups).sort((a,b)=>b[1].all-a[1].all);return `<div class="bar-chart">${data.map(([name,v])=>`<div class="bar-chart-row"><span title="${esc(name)}">${esc(name.length>23?name.slice(0,22)+'…':name)}</span><div class="bar-track"><i style="width:${v.done/v.all*100}%"></i></div><strong>${v.done}/${v.all}</strong></div>`).join('')}</div>`}
function collection(){const s=status();const missing=items().filter(x=>!pget(x.id).defeated).length;return sectionHead('DEIN ABENTEUER','Meine Sammlung','Erfolge, Wissensfortschritt und alle privaten Notizen werden in diesem Browser gesichert.')+`<div class="stat-grid">${statBox(s.k,'Besiegt',s.pct+' % der Kreaturen')}${statBox(s.missing,'Noch offen')}${statBox(s.w,'Wissen freigeschaltet',s.knowledgePct+' %')}${statBox(s.r,'Alle Belohnungen')}</div><section class="section"><div class="section-heading"><h2>Fortschritt pro Kategorie</h2></div><div class="detail-block">${ratioBars('category')}</div></section><section class="section"><div class="section-heading"><h2>Fortschritt pro Region</h2></div><div class="detail-block">${ratioBars('region')}</div></section><section class="section"><h2>Favoriten & zuletzt angesehen</h2><div class="actions">${btn('show-favs','Favoriten im Lexikon öffnen')}${btn('show-missing','Fehlende Kreaturen anzeigen')}${btn('show-done','Besiegte Kreaturen anzeigen')}</div><div class="section">${cards(items().filter(e=>pget(e.id).favorite).slice(0,8))}</div></section><section class="section"><h2>Datensicherung</h2><div class="detail-block"><p>Dein Fortschritt, persönliche Notizen, Favoriten und eigene Datenbankänderungen sind ausschließlich im lokalen Speicher deines Browsers. Exportiere regelmäßig eine Sicherung, besonders vor Browserwechsel oder dem Löschen von Website-Daten.</p><div class="actions">${btn('export','Gesamte Sammlung als JSON exportieren','primary')}${btn('import','JSON-Sicherung importieren')}${btn('export-database','Monsterdatenbank exportieren')}</div><p class="small-note" style="margin:14px 0 0">Import überschreibt nach Bestätigung die lokal gespeicherten Daten. Keine Cloud-Synchronisierung.</p></div></section>`}
function locations(){const valid=items().filter(e=>e.location&&!/Keine verifizierte genaue Position|Arenaposition nur soweit/.test(e.location)&&e.region!=='Nicht verifiziert');const regions=[...new Set(valid.map(e=>e.region))].sort((a,b)=>a.localeCompare(b,'de'));
 return sectionHead('FUNDORTKATALOG','Regionen & Spawn-Hinweise','Statt unzuverlässiger Koordinaten zeigt diese Ansicht dokumentierte Ortsangaben mit direkter Verknüpfung zum Monster-Guide.',`<a class="btn primary" href="${src.map||'https://crimsondesert.th.gl/guides'}" target="_blank" rel="noopener noreferrer">Externe Pywel-Karte ↗</a>`)+`<div class="callout"><strong>Keine Fake-Karte:</strong> Es stehen keine frei nutzbaren, sicher kartierbaren Weltkoordinaten im Projekt zur Verfügung. Die verifizierten Ortsbeschreibungen funktionieren offline; der externe Kartenanbieter erfordert Internet.</div><section class="section"><div class="filter-grid" style="margin-bottom:15px;grid-template-columns:repeat(2,minmax(0,1fr))"><label class="field">Region<select class="select" id="loc-region"><option value="">Alle Regionen</option>${regions.map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label class="field">Fundort suchen<input class="input" id="loc-search" type="search" placeholder="Zum Beispiel Arboria Castle"></label></div><div id="locations-results"></div></section><section class="section"><h2>Quellen für die Kartenrecherche</h2><div class="detail-block"><div class="sources-list"><a target="_blank" rel="noopener noreferrer" href="https://crimsondesert.th.gl/guides">The Hidden Gaming Lair – ortsbezogene Creature-Guides ↗</a><a target="_blank" rel="noopener noreferrer" href="https://www.powerpyx.com/crimson-desert-all-new-power-boss-locations/">PowerPyx – Fundorte der sieben „New Power“-Bosse ↗</a></div></div></section>`}
function renderLocations(){const wrap=$('locations-results');if(!wrap)return;const region=$('loc-region')?.value||'',q=($('loc-search')?.value||'').toLocaleLowerCase('de');const valid=items().filter(e=>e.location&&!/Keine verifizierte genaue Position|Arenaposition nur soweit/.test(e.location)&&e.region!=='Nicht verifiziert'&&(!region||e.region===region)&&[e.de,e.en,e.region,e.location].join(' ').toLocaleLowerCase('de').includes(q));const buckets={};for(const e of valid)(buckets[e.region]??=[]).push(e);wrap.innerHTML=valid.length?`<div class="location-grid">${Object.entries(buckets).sort().map(([r,es])=>`<section class="location-card"><h3>⌖ ${esc(r)} <small>(${es.length})</small></h3>${es.map(e=>`<div style="border-top:1px solid var(--line);padding:10px 0"><strong>${esc(shownName(e))}</strong><p style="margin:4px 0">${e.spoiler&&!store.settings.spoilers?'Storyinhalt verborgen':esc(e.location)}</p><button class="card-link" data-open="${esc(e.id)}">Fundort & Guide ansehen →</button></div>`).join('')}</section>`).join('')}</div>`:'<div class="empty">Keine dokumentierten Fundort-Hinweise für diese Auswahl.</div>'}
function combat(){const controls=[['Bewegen',['LS']],['Kamera',['RS']],['Leichter Angriff',['R1']],['Schwerer Angriff',['R2']],['Blocken / Parieren',['L1']],['Ausweichrolle',['○']],['Ausweichen (doppelt)',['○','○']],['Springen',['□']],['Sprinten (halten)',['✕']],['Trefferfokus',['✕']],['Schlagen / Treten',['△']],['Bogen zielen',['L2']],['Bogen abfeuern (L2 loslassen)',['L2']],['Force Palm',['R3']],['Axiom Force',['L3']],['Zielerfassung',['↓']],['Reittier rufen',['↑']],['Nahrung-Schnellzugriff (halten)',['→']],['Skill-Kombination 1',['R2','R1']],['Skill-Kombination 2',['R2','L1']],['Gegner werfen',['△','R1']],['Lariat',['△','R2']]];
 return sectionHead('KAMPFLEITFADEN','Fähigkeiten & PS5-Steuerung','Dokumentierte Standardaktionen; manche Fähigkeiten müssen im Spiel zuerst freigeschaltet werden.')+`<div class="callout"><strong>Controller-Hinweis:</strong> Die PS5-Zuordnung ist anhand veröffentlichter Controller-Guides abgeglichen. Aktuelle Updates, individuell geänderte Belegungen und kontextabhängige Befehle können abweichen. ✕ bedeutet Kreuz (nicht X auf der Tastatur).</div><section class="section"><h2>PS5-Grundbelegung</h2><div class="control-grid">${controls.map(([a,b])=>`<div class="control-item"><span>${esc(a)}</span><span class="combo">${kbds(b)}</span></div>`).join('')}</div></section><section class="section"><h2>Kampftaktiken</h2><div class="feature-grid"><div class="detail-block"><h3>Blocken und Parieren</h3><p>Gegen menschliche Gegner ist ein zeitlich gut gesetzter <strong>L1</strong>-Konter wirksam. Bei nicht blockbaren Monsterangriffen eher zur Seite ausweichen.</p></div><div class="detail-block"><h3>Schwere Angriffe</h3><p><strong>R2</strong> kann gegnerische Deckung durchbrechen. Ausdauer nicht bis null aufbrauchen: Eine Reserve für Ausweichbewegungen lassen.</p></div><div class="detail-block"><h3>Force Palm / Axiom Force</h3><p><strong>R3</strong> löst Force Palm aus, <strong>L3</strong> wird für Axiom Force genutzt. Fähigkeiten sind situationsabhängig; Bossguides erklären den Einsatz.</p></div><div class="detail-block"><h3>Heilen & Ausrüstung</h3><p>Vor schweren Bossen Heilnahrung vorbereiten. Upgrade-Stufen von Lebenspunkten, Rüstung und Waffen beeinflussen die Überlebenschance erheblich.</p></div></div></section><section class="section"><h2>Quellen zur Steuerung</h2><div class="sources-list"><a href="${src.ctrl}" target="_blank" rel="noopener noreferrer">games.gg – Controller-Befehle ↗</a><a href="https://www.scufgaming.com/us/en/gaming/games/general/best-controller-settings-for-crimson-desert/" target="_blank" rel="noopener noreferrer">SCUF – PS5-Steuerungsübersicht ↗</a><a href="${src.boss}" target="_blank" rel="noopener noreferrer">PowerPyx – Boss-Mechaniken ↗</a></div></section>`}
function findEntry(id){return items().find(x=>x.id===id)}
const formField=(key,label,val='',type='text')=>`<label class="field ${['description','location','attacks','strategy','steps','sources','notes'].includes(key)?'full':''}">${esc(label)}${type==='textarea'?`<textarea class="textarea" name="${key}" rows="${key==='steps'?4:2}">${esc(val)}</textarea>`:`<input class="input" name="${key}" type="${type}" value="${esc(val)}">`}</label>`;
function editForm(e){return `<form id="edit-form" class="detail-block"><h2>${e?'Eintrag bearbeiten':'Neuen Eintrag hinzufügen'}</h2><p class="small-note">Nur belegbare Fakten eintragen. Bei nicht bestätigten Daten „Unbekannt“ verwenden; Quellen-URLs je eine pro Zeile. Eigene Bilder mit Nutzungsrechten im Ordner assets ablegen und den Dateipfad angeben. Kein automatischer Webabgleich.</p><div class="form-grid">${formField('de','Deutscher Name',e?.de||'')}${formField('en','Englischer Name',e?.en||'')}${selectHTML('editor-category','Kategorie',Object.keys(categories).map(c=>[c,c]),e?.category||'Steinwürmer')}${selectHTML('editor-kind','Typ',[['Kreatur','Kreatur'],['Storyboss','Storyboss'],['Optionaler Weltboss','Optionaler Weltboss'],['Legendäres Tier','Legendäres Tier'],['Konstrukt','Konstrukt']],e?.kind||'Kreatur')}${formField('region','Region',e?.region||UNKNOWN)}${formField('difficulty','Schwierigkeit',e?.difficulty||'Unbekannt')}${formField('chapter','Kapitel (optional)',e?.chapter||'','number')}${formField('quest','Quest',e?.quest||'')}${formField('element','Element',e?.element||'Unbekannt')}${formField('weakness','Schwachstelle',e?.weakness||'Unbekannt')}${formField('resistance','Resistenzen',e?.resistance||'Unbekannt')}${formField('loot','Beute / Belohnungen',e?.loot||'Unbekannt')}${formField('image','Optionaler Bildpfad (assets/datei.png usw.)',e?.image||'')}${formField('location','Fundort',e?.location||'Unbekannt','textarea')}${formField('description','Beschreibung',e?.description||'','textarea')}${formField('attacks','Angriffsmuster',e?.attacks||'','textarea')}${formField('strategy','Kampftaktik',e?.strategy||'','textarea')}${formField('steps','Schritte (ein Schritt pro Zeile)',(e?.steps||[]).join('\n'),'textarea')}${formField('sources','Quellen (eine URL pro Zeile)',(e?.sources||[]).join('\n'),'textarea')}${formField('notes','Quellen- / Übersetzungshinweise',e?.notes||'','textarea')}<label class="toggle"><input name="spoiler" type="checkbox" ${e?.spoiler?'checked':''}>Storyspoiler</label></div><div class="actions" style="margin-top:20px"><button class="btn primary" type="submit">Eintrag speichern</button><button class="btn ghost" data-action="cancel-edit" type="button">Abbrechen</button>${e&&!base.some(x=>x.id===e.id)?`<button class="btn danger" data-action="delete-record" data-id="${esc(e.id)}" type="button">Eigenen Eintrag löschen</button>`:e?`<button class="btn danger" data-action="reset-record" data-id="${esc(e.id)}" type="button">Originaldatensatz wiederherstellen</button>`:''}</div></form>`}
function editor(){return sectionHead('DATENVERWALTUNG','Bestiarium erweitern','Füge Monster hinzu oder bearbeite bestehende Einträge. Änderungen sind lokal gespeichert und im Sicherungs-Export enthalten.',btn('new-record','+ Eintrag hinzufügen','primary'))+`<div class="callout"><strong>Grunddaten unverändert:</strong> Änderungen an bestehenden Einträgen werden als lokales Overlay gespeichert. So bleibt die mitgelieferte recherchierte Datenbank nachvollziehbar.</div>${editing!==null?editForm(editing==='NEW'?null:findEntry(editing)):`<section class="section"><div class="actions" style="margin-bottom:14px">${btn('export','Backup als JSON')}${btn('import','Backup importieren')}${btn('export-database','Datenbank separat exportieren')}</div><div class="filters"><div class="searchbox"><input class="input" id="editor-search" type="search" placeholder="Eintrag zur Bearbeitung suchen…" aria-label="Datenbank durchsuchen"></div></div><div id="editor-list">${renderEditorList('')}</div></section>`}`}
function renderEditorList(q){const a=items().filter(x=>[x.de,x.en,x.category].join(' ').toLowerCase().includes(q.toLowerCase())).slice(0,100);return `<p class="small-note">${a.length} Einträge angezeigt (maximal 100).</p>${a.map(e=>`<div class="boss-row"><img src="${art(e)}" loading="lazy" alt="Symbolillustration"><div class="boss-details"><strong>${esc(e.de)}</strong><small>${esc(e.en)} · ${store.overrides[e.id]?'Bearbeitet':store.custom.some(x=>x.id===e.id)?'Eigener Eintrag':'Grunddaten'}</small></div><button class="btn small ghost" data-action="edit-record" data-id="${esc(e.id)}">Bearbeiten</button></div>`).join('')}`}
function legal(){return sectionHead('TRANSPARENZ & URHEBERRECHT','Über dieses Fanprojekt','Unabhängiges, nicht-kommerzielles Bestiarium für die Community von Crimson Desert.')+
`<div class="legal-warning"><strong>Inoffizielles Fanprojekt – keine Zusammenarbeit mit Pearl Abyss</strong><p>Diese Website ist ein eigenständiges, kostenloses Community-Projekt. Sie enthält Namen und gegebenenfalls Bildmaterial aus Crimson Desert, an denen Pearl Abyss Corp. die Rechte hält. Die Website wurde weder von Pearl Abyss erstellt noch von Pearl Abyss geprüft, bestätigt, gesponsert oder unterstützt.</p></div>
<section class="section"><div class="detail-block"><h2>Urheberrecht & Bildnachweise</h2><p><strong>Crimson Desert</strong>, dessen Spielfiguren, Kreaturen, Ortsnamen, Spielaufnahmen, Logos und andere geschützte Spielinhalte sind Eigentum der jeweiligen Rechteinhaber, insbesondere Pearl Abyss Corp. © Pearl Abyss Corp. Alle Rechte vorbehalten.</p><p>Eigene Kategorie-Symbole und das Fantasy-Titelbild sind separat erstellte Illustrationen und keine Spielaufnahmen. Die zusätzlich als <em>offizielles Bildmaterial</em> gekennzeichneten Bilder stammen aus dem <a href="https://crimsondesert.pearlabyss.com/en-us/Media" target="_blank" rel="noopener noreferrer">Medienbereich von Crimson Desert / Pearl Abyss</a>. Copyright der offiziellen Screenshots: © Pearl Abyss Corp. Die Nutzung erfolgt als Fan-Content nach den Richtlinien von Pearl Abyss, nicht als Übertragung von Bildrechten.</p><p>Offizielle Screenshots dienen nur der allgemeinen Illustration; sie sind nicht automatisch einem konkreten Gegner oder verifizierten Spawn-Ort zugeordnet. Eigene redaktionelle Texte sind keine offiziellen Spielanleitungen.</p></div></section>
<section class="section"><div class="detail-block"><h2>Geltende Fan-Content-Richtlinien</h2><p>Diese Website erhebt keine Zugangsgebühr und enthält keine eingebauten Werbeplätze oder Bezahldienste. Wir achten auf die offizielle Unterscheidung zwischen Fanbeiträgen und Veröffentlichungen des Entwicklers.</p><div class="sources-list"><a href="https://crimsondesert.pearlabyss.com/de-de/Policy?_policyNo=130" target="_blank" rel="noopener noreferrer">Pearl Abyss: Richtlinien für Fan-Content (deutsch) ↗</a><a href="https://crimsondesert.pearlabyss.com/en-US/News/Notice/Detail?_boardNo=25" target="_blank" rel="noopener noreferrer">Crimson Desert: offizielles Fan-Kit und Bildhinweise ↗</a><a href="https://crimsondesert.pearlabyss.com/en-us/Media" target="_blank" rel="noopener noreferrer">Pearl Abyss: Medien / Screenshots ↗</a></div><p>Fragen zu konkreten Nutzungsfällen beantwortet Pearl Abyss unter <a href="mailto:fancontent@pearlabysscorp.com">fancontent@pearlabysscorp.com</a>. Eine Antwortlosigkeit stellt keine Zustimmung dar.</p></div></section>
<section class="section"><div class="detail-block"><h2>Datenschutz und Zuverlässigkeit</h2><p>Persönlicher Fortschritt, Favoriten und Notizen werden ausschließlich im Browser (localStorage) gespeichert und nicht an einen eigenen Server übertragen. Das Aufrufen externer Quellen, Bilder von Pearl Abyss oder externer Karten kann Verbindungen zum jeweiligen Drittanbieter herstellen. Du kannst den Fortschritt jederzeit als JSON exportieren.</p><p>Bestätigte Daten sind von Guide-Angaben und unbekannten Werten getrennt. Deutsche Gegnernamen können redaktionelle Übersetzungen sein. Änderungen und Quellen werden transparent aufgeführt; neue Patches können Angaben verändern.</p></div></section>`}
function sources(){return sectionHead('NACHVOLLZIEHBAR & TRANSPARENT','Quellen und Änderungen','Hier stehen die verwendeten Referenzen, Qualitätsgrenzen und der redaktionelle Datenstand.')+`<div class="detail-block"><h2>Was als bestätigt gilt</h2><p><strong>Name bestätigt:</strong> der Gegner ist in einer öffentlich zugänglichen Datenbank aufgeführt. <strong>Guide belegt:</strong> konkrete Taktik oder Fundort wird von einem benannten Guide berichtet. <strong>Teilweise recherchiert:</strong> einzelne Mechaniken oder Beute gelten nur für eine Familie oder Guidefassung.</p><p>Diese Kennzeichnung ist keine Garantie für Vollständigkeit. Englische Originalnamen sind bevorzugt; deutsche Namen sind, sofern nicht ausdrücklich offiziell belegt, redaktionelle Arbeitsübersetzungen. Keine abgeleiteten Koordinaten, erfundenen Drop-Raten oder ungeprüften Elementarschwächen.</p></div><section class="section"><h2>Primär- und Guidequellen</h2><div class="detail-block sources-list">${Object.entries(src).map(([k,u])=>`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc({cam:'Getarnte Kreaturen (gaming.tools)',legen:'Legendäre Tiere (gaming.tools)',walk:'Magische Walker (gaming.tools)',mech:'Maschinenkreaturen (gaming.tools)',insect:'Insekten (gaming.tools)',boss:'Storyboss-Guide (PowerPyx)',power:'Sieben New-Power-Bosse (PowerPyx)',bossdb:'Boss-Datenbank (CrimsonDB)',map:'Ortsbezogene Karten-Guides (TH.GL)',ctrl:'PS5-Controllerbelegung (games.gg)',patch:'Offizielle DLC-Ankündigung (Pearl Abyss)'}[k]||k)} ↗</a>`).join('')}<a href="https://crimsondesert.pearlabyss.com/de-de/News/Notice" target="_blank" rel="noopener noreferrer">Offizielle Patchnotes – Pearl Abyss ↗</a></div></section><section class="section"><h2>Änderungsprotokoll</h2><div class="detail-block"><h3>27.10.2026 · Ausgabe 1.1</h3><p>Deutliche Kennzeichnung als unabhängiges Fanprojekt; gesonderte Seite zu Bildrechten, Fan-Content und Datenschutz; zwei offiziell gekennzeichnete Screenshots; Boss-Revanche nach offiziellen Patchnotes und überarbeitete Kreaturen-Daten.</p><h3>27.10.2026 · Ausgabe 1.0</h3><p>Erstfassung mit ${items().length} Einträgen, Kampfguides, Kategorie-Illustrationen, Regionensuche, lokalem Fortschrittssystem, Backup-Funktionen und eingebautem Dateneditor.</p><h3>September 2026 · Quellenlage</h3><p>gaming.tools meldet Datenbankversion 2.0.0 (Stand 30.09.2026). Der neue DLC „Charting the Unknown“ ist zum Bearbeitungszeitpunkt noch nicht veröffentlicht; angekündigte Unterwasserinhalte wurden bewusst nicht als schon dokumentierte Gegner aufgenommen.</p><h3>Eigene Änderungen</h3><p>${Object.keys(store.overrides).length} lokal bearbeitete Basiseinträge; ${store.custom.length} selbst hinzugefügte Einträge. Beides wird im JSON-Backup mitgesichert.</p></div></section>`}
function writeFile(file,content){const blob=new Blob([content],{type:'application/json;charset=utf-8'}),a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download=file;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),3000);notify('JSON-Datei zum Herunterladen bereitgestellt.')}
function exportAll(){writeFile('pywel-bestiarium-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify({application:'pywel-bestiary',schema:1,exportedAt:new Date().toISOString(),data:store},null,2))}
function exportDatabase(){writeFile('pywel-monsterdaten-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(items(),null,2))}
function incoming(obj){if(!obj||obj.application!=='pywel-bestiary'||obj.schema!==1||!obj.data||typeof obj.data!=='object')throw Error('Keine gültige Pywel-Sicherungsdatei.');const x=obj.data;if(!x.progress||typeof x.progress!=='object'||Array.isArray(x.progress)||!Array.isArray(x.custom)||typeof x.overrides!=='object')throw Error('Unvollständige Backup-Daten.');if(x.custom.length>2000||Object.keys(x.progress).length>20000)throw Error('Sicherungsdatei überschreitet Sicherheitsgrenzen.');const validRec=r=>r&&typeof r==='object'&&typeof r.id==='string'&&/^[a-z0-9-]{1,100}$/.test(r.id)&&typeof r.en==='string'&&r.en.length<=220&&typeof r.de==='string'&&r.de.length<=220&&categories[r.category]&&(!r.sources||Array.isArray(r.sources));if(!x.custom.every(validRec))throw Error('Ungültiger benutzerdefinierter Monstereintrag.');for(const [k,r] of Object.entries(x.overrides)){if(!base.some(e=>e.id===k)||!validRec(r))throw Error('Ungültige Änderung: '+k)};return {version:1,progress:x.progress,custom:x.custom,overrides:x.overrides,settings:{...initial.settings,...(x.settings||{})},recent:Array.isArray(x.recent)?x.recent.slice(0,8):[]}}
function doAction(act,node){const id=node?.dataset?.id;switch(act){case 'toggle-spoiler':store.settings.spoilers=!store.settings.spoilers;save();render();notify('Spoiler '+(store.settings.spoilers?'eingeschaltet':'ausgeblendet'));break;case 'clear-filters':Object.assign(filter,{search:'',category:'',region:'',difficulty:'',element:'',weakness:'',type:'',status:'',knowledge:'',favorites:false,sort:'name'});render();break;case 'go-back':goto(lastPage||'lexikon');break;case 'print':window.print();break;case 'export':exportAll();break;case 'export-database':exportDatabase();break;case 'import':$('import-file').click();break;case 'show-favs':filter.favorites=true;goto('lexikon');break;case 'show-missing':filter.status='no';goto('lexikon');break;case 'show-done':filter.status='yes';goto('lexikon');break;case 'new-record':editing='NEW';render();break;case 'edit-record':editing=id;goto('daten');render();break;case 'cancel-edit':editing=null;render();break;case 'increment-kills':case 'decrement-kills':{const n=Math.max(0,Math.min(999999,(Number(pget(id).kills)||0)+(act==='increment-kills'?1:-1)));pset(id,{kills:n});const inp=$('kills-'+id);if(inp)inp.value=n;break}case 'reset-record':if(confirm('Eigene Änderungen an diesem Eintrag zurücksetzen?')){delete store.overrides[id];save();editing=null;render();notify('Grunddatensatz wiederhergestellt.')}break;case 'delete-record':if(confirm('Diesen eigenen Monstereintrag wirklich löschen?')){store.custom=store.custom.filter(x=>x.id!==id);delete store.progress[id];save();editing=null;render();notify('Eintrag gelöscht.')}break;}}
function syncFilter(){if(!$('filter-search'))return;filter.search=$('filter-search').value;for(const [field,id] of [['category','f-category'],['region','f-region'],['difficulty','f-difficulty'],['element','f-element'],['weakness','f-weakness'],['type','f-type'],['status','f-status'],['knowledge','f-knowledge'],['sort','f-sort']])filter[field]=$(id).value;filter.favorites=$('f-fav').checked;renderFiltered()}
function saveRecord(form){const fd=new FormData(form),name=String(fd.get('en')||'').trim(),de=String(fd.get('de')||'').trim();if(!name||!de){notify('Deutscher und englischer Name sind erforderlich.');return}if(name.length>220||de.length>220){notify('Name zu lang.');return}const original=editing&&editing!=='NEW'?findEntry(editing):null;let id=original?.id||slug(name);if(!id){notify('Ungültiger Name.');return}if(!original&&items().some(e=>e.id===id)){notify('Eintrag existiert bereits. Bitte vorhandenen Eintrag bearbeiten.');return}const line=k=>String(fd.get(k)||'').trim();const raw=original||{};const category=$('editor-category').value,kind=$('editor-kind').value;
 const e={...raw,id,de,en:name,category,kind,region:line('region')||UNKNOWN,location:line('location')||UNKNOWN,difficulty:line('difficulty')||'Unbekannt',element:line('element')||'Unbekannt',weakness:line('weakness')||'Unbekannt',resistance:line('resistance')||'Unbekannt',loot:line('loot')||'Unbekannt',quest:line('quest')||'Unbekannt',image:/^assets\/[a-zA-Z0-9_.-]+\.(png|jpg|jpeg|webp|svg)$/i.test(line('image'))&&!line('image').includes('..')?line('image'):'',description:line('description')||'Noch keine Beschreibung hinterlegt.',attacks:line('attacks')||'Unbekannt',strategy:line('strategy')||'Unbekannt',steps:line('steps').split(/\r?\n/).map(x=>x.trim()).filter(Boolean),sources:line('sources').split(/\r?\n/).map(x=>x.trim()).filter(Boolean).filter(url),notes:line('notes'),spoiler:fd.get('spoiler')==='on',chapter:line('chapter')?Number(line('chapter')):null,verified:new Date().toISOString().slice(0,10),confidence:'mixed',buttons:raw.buttons||['R1','R2','○','L1'],skills:raw.skills||[],weapons:raw.weapons||'Unbekannt',spawns:raw.spawns||[],related:raw.related||[]};
 if(!categories[category]){notify('Ungültige Kategorie.');return}if(original&&base.some(x=>x.id===original.id))store.overrides[id]=e;else if(original)store.custom=store.custom.map(x=>x.id===id?e:x);else store.custom.push(e);save();editing=null;goto('monster/'+id);notify('Eintrag lokal gespeichert.')}
function render(){const {a,b}=getHash();route=['start','lexikon','boss','fundorte','sammlung','kampf','daten','quellen','rechtliches','monster'].includes(a)?a:'start';if(route==='monster'){const e=byId(b);if(e)visit(e.id);setPage(detail(e));}else{if(route!=='daten')editing=null;setPage(({start:dashboard,lexikon,boss:bossPage,fundorte:locations,sammlung:collection,kampf:combat,daten:editor,quellen:sources,rechtliches:legal})[route]())}navRender();if(route==='fundorte')renderLocations();window.scrollTo({top:0,behavior:'instant'});$('sidebar').classList.remove('open');$('menu-btn').setAttribute('aria-expanded','false');$('backdrop').hidden=true}
document.addEventListener('click',ev=>{const c=ev.target.closest('button,[data-open],[data-category]');if(!c)return;if(c.matches('button[data-track="favorite"]')){ev.preventDefault();ev.stopPropagation();const id=c.dataset.id;const active=!pget(id).favorite;pset(id,{favorite:active});if(route==='lexikon'&&filter.favorites){renderFiltered()}else if(route==='start'||route==='sammlung'||route==='boss'){render()}else{c.classList.toggle('is-on',active);c.setAttribute('aria-pressed',String(active));c.textContent=active?'★':'☆'}return}if(c.dataset.track)return;if(c.dataset.open){lastPage=route==='monster'?lastPage:route;goto('monster/'+c.dataset.open);return}if(c.dataset.category){filter.category=c.dataset.category;goto('lexikon');return}if(c.dataset.view){filter.view=c.dataset.view;render();return}if(c.dataset.action){ev.preventDefault();doAction(c.dataset.action,c)}});
document.addEventListener('keydown',ev=>{const x=ev.target.closest('[data-open][role="link"]');if(x&&(ev.key==='Enter'||ev.key===' ')){ev.preventDefault();lastPage=route;goto('monster/'+x.dataset.open)}});
document.addEventListener('change',ev=>{const el=ev.target;if(el.dataset.track){const p=pget(el.dataset.id);pset(el.dataset.id,{[el.dataset.track]:!!el.checked});if(route==='sammlung'||route==='start'||route==='boss'||route==='lexikon')render();return}if(el.dataset.kills){pset(el.dataset.kills,{kills:Math.max(0,Math.min(999999,parseInt(el.value,10)||0))});return}if(el.id?.startsWith('f-'))syncFilter();if(el.id==='loc-region')renderLocations()});
document.addEventListener('input',ev=>{const el=ev.target;if(el.dataset.note){pset(el.dataset.note,{notes:el.value});return}if(el.id==='filter-search'){filter.search=el.value;renderFiltered()}if(el.id==='loc-search')renderLocations();if(el.id==='editor-search')$('editor-list').innerHTML=renderEditorList(el.value)});
document.addEventListener('submit',e=>{if(e.target.id==='edit-form'){e.preventDefault();saveRecord(e.target)}});
$('import-file').addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;try{if(f.size>8e6)throw Error('Datei größer als 8 MB.');const obj=JSON.parse(await f.text()),next=incoming(obj);if(confirm('Die JSON-Sicherung ersetzt alle lokalen Fortschritte, Notizen und Änderungen. Fortfahren?')){store=next;save();editing=null;render();notify('Sicherung erfolgreich importiert.')}}catch(err){notify('Import abgebrochen: '+(err?.message||'Ungültige Datei'))}finally{e.target.value=''}});
$('theme-toggle').addEventListener('click',()=>{store.settings.light=!store.settings.light;save();updateSidebar()});$('spoiler-toggle').addEventListener('click',()=>doAction('toggle-spoiler',{}));$('favorite-shortcut').addEventListener('click',()=>{filter.favorites=true;goto('lexikon');if(route==='lexikon')render()});$('menu-btn').addEventListener('click',()=>{const active=$('sidebar').classList.toggle('open');$('menu-btn').setAttribute('aria-expanded',String(active));$('backdrop').hidden=!active});$('backdrop').addEventListener('click',()=>{$('sidebar').classList.remove('open');$('menu-btn').setAttribute('aria-expanded','false');$('backdrop').hidden=true});window.addEventListener('hashchange',render);
if(!location.hash)location.replace('#/start');render();
})();
